SOURCE = zlib.decompress(base64.b85decode(BLOB)).decode("utf-8")
WORK = Path("/kaggle/working") if Path("/kaggle/working").exists() else Path.cwd()
MAIN = WORK / "main.py"
ARCHIVE = WORK / "submission.tar.gz"
MAIN.write_text(SOURCE, encoding="utf-8")
namespace = {}
exec(compile(SOURCE, "main.py", "exec"), namespace)
environment = make("kaggriculture", configuration={"episodeSteps": 720, "seed": 1701}, debug=False)
final = environment.run([namespace["agent"], "starter"])[-1]
assert [state.status for state in final] == ["DONE", "DONE"]
with tarfile.open(ARCHIVE, "w:gz") as bundle:
    bundle.add(MAIN, arcname="main.py")
assert ARCHIVE.exists()
